            ,MBR_CD
            ,BRD_TITL_NM
            ,BRD_CONT
            ,BRD_PBLS_DTM
            ,BRD_VW_CNT
            , BRD_DEL_YN
        ) VALUES (
            #{brdNo}
            ,'A0001'
            ,#{mbrCd}
            ,#{brdTitlNm}
            ,#{brdCont}
            ,SYSDATE
            ,0
            ,'N'
        )
